Local Abbreviation SEGS := Plain.M.loaded_segments.

Section RopGen14W.
Context {fx : FPState} {AL : AllocLayout} {CL : CallocLayout} {ASR : AllocSure}.
Context {PINS : @LeptPins AL LL16} {P16 : O23Pins}.
#[local] Notation "'u'" := bv_unsigned (only parsing).

(* [comment removed for export] *)
Lemma rg14_F_W : forall (n : nat) C Ar A md (s : Z) (S : TSet) (f : frw) (fl : word)
    (datad nd datas ns psf pdf swpl dwpl dh x2 : Z) (f6 f7 : bool) (r0 : bvmap 5 word) m0 m r (i : Z),
  rg_ok C Ar A md s datad nd datas ns ->
  (1 <= dh < 2 ^ 24)%Z -> (0 <= swpl < 2 ^ 24)%Z -> (0 <= dwpl < 2 ^ 24)%Z -> (x2 = if f6 && negb f7 then 4 else 0)%Z ->
  (forall i', 0 <= i' < dh -> datad <= pdf + 4 * dwpl * i' /\ pdf + 4 * dwpl * i' + 4 <= datad + nd)%Z ->
  (forall i', 0 <= i' < dh -> datas <= psf + 4 * swpl * i' /\ psf + 4 * swpl * i' + 4 + x2 <= datas + ns)%Z ->
  (Z.of_nat n = dh - 1 - i)%Z -> (0 <= i < dh)%Z ->
  rg_st C Ar A md s datad nd m0 f fl m ->
  regs_agree (fun x => In x [1; 7; 8; 22; 23; 31]%list) r0 r ->
  getr r 1 = Z_to_bv 64 (psf + 4 * swpl * i + 4) -> getr r 8 = Z_to_bv 64 (pdf + 4 * dwpl * i) -> getr r 22 = Z_to_bv 64 (dh - i) ->
  getr r0 13 = Z_to_bv 64 (4 * swpl) -> getr r0 14 = Z_to_bv 64 (4 * dwpl) ->
  getr r0 20 = Z_to_bv 64 (if f6 then 1 else 0) -> getr r0 21 = Z_to_bv 64 (if f7 then 1 else 0) ->
  (forall m' r', rg_st C Ar A md s datad nd m0 f fl m' -> regs_agree (fun x => In x [1; 7; 8; 22; 23; 31]%list) r0 r' ->
     realizes SEGS (mkCfg (mkst r' (0x7b4c0 : word) m' al_rom) md) S) ->
