(* [comment removed for export] *)
Lemma rg14_G_W : forall (n : nat) C Ar A md (s : Z) (S : TSet) (f : frw) (fl : word)
    (datad nd datas ns psF pdF nfw swpl dwpl dh : Z) (r0 : bvmap 5 word) m0 m r (i : Z),
  rg_ok C Ar A md s datad nd datas ns -> (1 <= nfw < 2 ^ 26)%Z ->
  (1 <= dh < 2 ^ 24)%Z -> (0 <= swpl < 2 ^ 24)%Z -> (0 <= dwpl < 2 ^ 24)%Z ->
  (forall i', 0 <= i' < dh -> datad <= pdF + 4 * dwpl * i' /\ pdF + 4 * dwpl * i' + 4 * nfw <= datad + nd)%Z ->
  (forall i', 0 <= i' < dh -> datas <= psF + 4 * swpl * i' /\ psF + 4 * swpl * i' + 4 * nfw + 4 <= datas + ns)%Z ->
  (Z.of_nat n = dh - 1 - i)%Z -> (0 <= i < dh)%Z ->
  rg_st C Ar A md s datad nd m0 f fl m ->
  regs_agree (fun x => In x [7; 8; 9; 11; 19; 20; 21; 22; 23; 31]%list) r0 r ->
  getr r 11 = Z_to_bv 64 i -> getr r 8 = Z_to_bv 64 i -> getr r 9 = Z_to_bv 64 (psF + 4 * swpl * i + 4) -> getr r 19 = Z_to_bv 64 (pdF + 4 * dwpl * i) ->
  getr r0 28 = Z_to_bv 64 nfw -> getr r0 14 = Z_to_bv 64 (4 * dwpl) -> getr r0 13 = Z_to_bv 64 (4 * swpl) -> getr r0 18 = Z_to_bv 64 (4 * nfw) ->
  getr r0 29 = Z_to_bv 64 pdF -> getr r0 12 = Z_to_bv 64 dh ->
  (forall m' r', rg_st C Ar A md s datad nd m0 f fl m' -> regs_agree (fun x => In x [7; 8; 9; 11; 19; 20; 21; 22; 23; 31]%list) r0 r' ->
     realizes SEGS (mkCfg (mkst r' (0x7b4c4 : word) m' al_rom) md) S) ->
